async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// QA-10 — Janitor de QA. Arregla el problema de fondo: la limpieza de datos
// sintéticos ya NO depende de que el runner sobreviva hasta el final.
//
// Si un runner muere a media corrida (timeout de 300s, reinicio, despliegue),
// deja leads/conversaciones falsos en producción y un run atascado en RUNNING.
// Este workflow, con horario propio, los barre solos y avisa si tuvo que hacerlo
// (porque significa que algo se murió y quieres enterarte).
//
// SEGURIDAD: los filtros exigen SIEMPRE las dos condiciones que identifican un
// dato sintético sin ambigüedad -- quicklink_id >= 990000000 Y el teléfono de QA.
// Nunca puede tocar un lead real. Además solo borra filas con más de AGE_MIN
// minutos, muy por encima de lo que dura cualquier corrida legítima.
const SB_URL = 'https://quicklink.spb.aigentss.cloud';
const SRK = '${REDACTED_JWT}';
const H = { apikey: SRK, Authorization: 'Bearer ' + SRK, 'Content-Type': 'application/json' };
const AGE_MIN = 45;
const QA_PHONE = 'like.*998299109*';
const helpers = this.helpers;
const nowIso = () => new Date().toISOString();

async function sb(method, path, payload, prefer) {
  const headers = Object.assign({}, H);
  if (prefer) headers.Prefer = prefer;
  const opt = { method, url: SB_URL + '/rest/v1/' + path, headers, json: true,
                returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 };
  if (payload !== undefined) opt.body = payload;
  const r = await __salesProdHttpRequest.call(this, opt);
  if (r.statusCode < 200 || r.statusCode >= 300) {
    throw new Error(method + ' ' + path + ' -> ' + r.statusCode + ' ' + JSON.stringify(r.body).slice(0, 160));
  }
  return r.body;
}

const cutoff = new Date(Date.now() - AGE_MIN * 60000).toISOString();
const report = { cutoff, stuck_runs: 0, deleted_convs: 0, deleted_leads: 0, errors: [] };

// 1) Runs atascados en RUNNING: el proceso murió sin finalizarlos.
try {
  const stuck = await sb('GET', 'cris_test_runs?status=eq.RUNNING&started_at=lt.' + cutoff + '&select=id,run_key') || [];
  for (const r of stuck) {
    await sb('PATCH', 'cris_test_runs?id=eq.' + r.id, {
      status: 'FAILED', finished_at: nowIso(),
      summary: { error: 'abortado: la corrida nunca finalizó (barrida por QA-10 janitor)' },
    }, 'return=minimal');
  }
  report.stuck_runs = stuck.length;
} catch (e) { report.errors.push('runs: ' + String(e.message || e).slice(0, 160)); }

// 2) Filas sintéticas huérfanas.
let convs = [], leads = [];
try {
  convs = await sb('GET', 'conversaciones?quicklink_id=gte.990000000&telefono=' + QA_PHONE +
                   '&updated_at=lt.' + cutoff + '&select=id,lead_id') || [];
  leads = await sb('GET', 'leads_quicklink?quicklink_id=gte.990000000&telefono_1=' + QA_PHONE +
                   '&updated_at=lt.' + cutoff + '&select=id') || [];
} catch (e) { report.errors.push('scan: ' + String(e.message || e).slice(0, 160)); }

const cids = convs.map(c => c.id);
const lids = Array.from(new Set(convs.map(c => c.lead_id).filter(Boolean).concat(leads.map(l => l.id))));

if (cids.length) {
  const ci = cids.join(',');
  // La memoria puede apuntar a una conversación que vamos a borrar.
  try {
    const mem = await sb('GET', 'lead_memory?phone=' + QA_PHONE + '&select=conversation_id&limit=1') || [];
    if (mem[0] && cids.indexOf(mem[0].conversation_id) >= 0) {
      await sb('PATCH', 'lead_memory?phone=' + QA_PHONE, { conversation_id: null }, 'return=minimal');
    }
  } catch (e) { report.errors.push('mem: ' + String(e.message || e).slice(0, 120)); }
  const dep = [['scheduled_followups', 'conversation_id'], ['eventos_conversacion', 'conversacion_id'],
    ['eventos_conversacion', 'conversation_id'], ['transferencias_humano', 'conversacion_id'],
    ['datos_calificacion', 'conversation_id'], ['conversation_memory', 'conversation_id'],
    ['agent_decisions', 'conversation_id'], ['sync_queue', 'conversation_id'],
    ['intentos_contacto', 'conversacion_id'], ['whatsapp_interaction_events', 'conversation_id']];
  for (const d of dep) {
    try { await sb('DELETE', d[0] + '?' + d[1] + '=in.(' + ci + ')', undefined, 'return=minimal'); } catch (e) {}
  }
  try {
    await sb('DELETE', 'conversaciones?id=in.(' + ci + ')&quicklink_id=gte.990000000', undefined, 'return=minimal');
    report.deleted_convs = cids.length;
  } catch (e) { report.errors.push('conv: ' + String(e.message || e).slice(0, 160)); }
}

if (lids.length) {
  try {
    await sb('DELETE', 'leads_quicklink?id=in.(' + lids.join(',') + ')&quicklink_id=gte.990000000',
             undefined, 'return=minimal');
    report.deleted_leads = lids.length;
  } catch (e) { report.errors.push('leads: ' + String(e.message || e).slice(0, 160)); }
}

// Solo alerta si hubo que barrer algo (o si el propio janitor falló):
// que limpie es la señal de que una corrida se murió a medias.
const dirty = report.stuck_runs + report.deleted_convs + report.deleted_leads;
const alert = dirty > 0 || report.errors.length > 0;
let meta_payload = null;
if (alert) {
  const lines = ['CRIS QA — Janitor barrió residuos', ''];
  if (report.stuck_runs) lines.push('runs atascados cerrados: ' + report.stuck_runs);
  if (report.deleted_convs) lines.push('conversaciones sintéticas borradas: ' + report.deleted_convs);
  if (report.deleted_leads) lines.push('leads sintéticos borrados: ' + report.deleted_leads);
  if (report.errors.length) lines.push('errores: ' + report.errors.join(' | ').slice(0, 400));
  lines.push('');
  lines.push('Significa que una corrida de QA murió sin limpiar (timeout/reinicio).');
  meta_payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: '5521999910781',
    type: 'text', text: { preview_url: false, body: lines.join('\n').slice(0, 3900) } };
}
return [{ json: Object.assign({ send_alert: alert, meta_payload }, report) }];
